// GuardRail - step 1: normalise the submission and validate it before anything else.
const NL = String.fromCharCode(10);
const raw = $json;
function pick(keys) {
  for (const k of keys) {
    if (raw[k] !== undefined && raw[k] !== null && String(raw[k]).trim() !== '') return raw[k];
  }
  return '';
}
function mod97(s) {
  const rearr = s.slice(4) + s.slice(0, 4);
  let rem = 0;
  for (let i = 0; i < rearr.length; i++) {
    const ch = rearr[i];
    const val = ch >= 'A' && ch <= 'Z' ? String(ch.charCodeAt(0) - 55) : ch;
    for (let j = 0; j < val.length; j++) rem = (rem * 10 + Number(val[j])) % 97;
  }
  return rem;
}
const vendor_code = String(pick(['Vendor code', 'vendor_code'])).trim().toUpperCase();
const requested_by = String(pick(['Requested by (email)', 'requested_by'])).trim().toLowerCase();
const account_holder = String(pick(['New account holder', 'new_account_holder'])).trim();
const iban = String(pick(['New IBAN', 'new_iban'])).replace(/[\s-]+/g, '').toUpperCase();
const bank_country = String(pick(['New bank country', 'new_bank_country'])).trim().toUpperCase();
const reason = String(pick(['Reason', 'reason'])).trim();

const errors = [];
if (!vendor_code) errors.push('vendor code is missing');
else if (!/^[A-Z0-9_.-]{2,32}$/.test(vendor_code)) errors.push('vendor code has invalid characters');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(requested_by)) errors.push('requester email is not valid');
if (account_holder.length < 2) errors.push('account holder is missing');
if (reason.length < 10) errors.push('reason must be at least 10 characters');
if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$/.test(iban)) errors.push('IBAN format is invalid');
else if (mod97(iban) !== 1) errors.push('IBAN checksum does not match (likely a typo)');
if (!/^[A-Z]{2}$/.test(bank_country)) errors.push('bank country must be a 2-letter ISO code');
if (iban && bank_country && iban.slice(0, 2) !== bank_country) errors.push('bank country does not match the IBAN prefix');

const now = new Date();
const at = now.toISOString().slice(0, 16).replace('T', ' ');
return [{
  json: {
    vendor_code: vendor_code,
    requested_by: requested_by,
    account_holder: account_holder,
    new_iban: iban,
    new_iban_masked: iban ? iban.slice(0, 4) + ' **** ' + iban.slice(-4) : '',
    iban_country: iban ? iban.slice(0, 2) : '',
    bank_country: bank_country,
    reason: reason,
    submitted_at: now.toISOString(),
    valid: errors.length === 0,
    errors: errors.join('; '),
    event: 'SUBMISSION_REJECTED',
    change_id: '',
    actor: requested_by || 'unknown',
    detail: errors.join('; '),
    at: at
  }
}];

// GuardRail - step 2: match the vendor, score the risk and decide the route.
// Routes: pending (send verification link) | duplicate (ignore, already open) | manual (never auto-approvable)
const cfg = $('Config (intake)').first().json;
const item = $json;
const vendors = $('Read vendors').all().map(function (i) { return i.json; });
const history = $('Read change history').all().map(function (i) { return i.json; });
function norm(v) { return String(v === null || v === undefined ? '' : v).trim().toLowerCase(); }
function daysAgo(v) {
  const t = new Date(v).getTime();
  return isFinite(t) ? (Date.now() - t) / 86400000 : 9999;
}
const FREE_MAIL = ['gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'icloud.com', 'aol.com', 'proton.me', 'gmx.com'];
const vendor = vendors.find(function (v) { return norm(v.vendor_code) === norm(item.vendor_code); });
const flags = [];
let risk = 0;

if (!vendor) {
  flags.push('UNKNOWN_VENDOR');
  risk = 100;
} else {
  if (norm(vendor.status) && norm(vendor.status) !== 'active') { flags.push('VENDOR_NOT_ACTIVE'); risk += 40; }
  if (vendor.country && item.iban_country && norm(vendor.country) !== norm(item.iban_country)) { flags.push('BANK_COUNTRY_MISMATCH'); risk += 30; }
  const requesterDomain = item.requested_by.split('@')[1] || '';
  if (vendor.vendor_domain && norm(vendor.vendor_domain) !== norm(requesterDomain)) { flags.push('REQUESTER_DOMAIN_MISMATCH'); risk += 25; }
  if (FREE_MAIL.indexOf(norm(requesterDomain)) >= 0) { flags.push('FREE_MAIL_REQUESTER'); risk += 15; }
  if (!String(vendor.finance_email || '').trim()) { flags.push('NO_FINANCE_CONTACT'); risk = Math.max(risk, 70); }
  const recentChanges = history.filter(function (h) { return norm(h.vendor_code) === norm(item.vendor_code) && daysAgo(h.created_at) <= 90; }).length;
  if (recentChanges >= 2) { flags.push('FREQUENT_CHANGES_90D'); risk += 30; }
  else if (recentChanges === 1) { flags.push('SECOND_CHANGE_90D'); risk += 15; }
}
risk = Math.min(100, risk);

const duplicate = history.some(function (h) {
  return norm(h.iban_hash) === norm(item.iban_hash) && ['PENDING_VERIFICATION', 'APPROVED'].indexOf(String(h.status || '').toUpperCase()) >= 0;
});
let route = 'pending';
if (duplicate) route = 'duplicate';
else if (!vendor || risk >= 70) route = 'manual';

const cooling = risk >= 40 ? Number(cfg.cooling_hours_high) : Number(cfg.cooling_hours_standard);
const stamp = new Date();
const change_id = 'BC-' + stamp.toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
const status = route === 'pending' ? 'PENDING_VERIFICATION' : route === 'duplicate' ? 'DUPLICATE_IGNORED' : 'MANUAL_REVIEW';

return [{
  json: Object.assign({}, item, {
    route: route,
    risk: risk,
    risk_flags: flags.join(', '),
    cooling_hours: cooling,
    change_id: change_id,
    vendor_name: vendor ? vendor.vendor_name : item.vendor_code,
    finance_email: vendor ? String(vendor.finance_email || '') : '',
    finance_lead_email: vendor ? String(vendor.finance_lead_email || '') : String(cfg.finance_lead || ''),
    status: status,
    event: route === 'pending' ? 'CHANGE_HELD' : route === 'duplicate' ? 'DUPLICATE_IGNORED' : 'MANUAL_REVIEW_REQUIRED',
    actor: item.requested_by,
    detail: route + ' | risk ' + risk + ' | ' + (flags.join(', ') || 'no flags'),
    at: stamp.toISOString().slice(0, 16).replace('T', ' ')
  })
}];

// GuardRail - step 3: build the single-use links. The token and its hash come from the two Crypto nodes.
const cfg = $('Config (intake)').first().json;
const it = $json;
const token = it.token;
const token_hash = it.token_hash;
const now = new Date();
const addHours = function (h) { return new Date(now.getTime() + Number(h) * 3600000).toISOString(); };
const base = String(cfg.base_url || '').replace(/\/+$/, '');
if (!/^https?:\/\//.test(base)) throw new Error('Set base_url in "Config (intake)" before activating: it is required to build the approval links.');
const approve = base + '/webhook/vendor-bank-decision?t=' + token + '&d=approve';
const reject = base + '/webhook/vendor-bank-decision?t=' + token + '&d=reject';
const company = cfg.company || 'your finance team';
const NL = String.fromCharCode(10);

const body = [
  'A change of bank details was requested for vendor ' + it.vendor_name + ' (' + it.vendor_code + ').',
  '',
  'Requested by: ' + it.requested_by,
  'New account holder: ' + it.account_holder,
  'New IBAN: ' + it.new_iban_masked,
  'Bank country: ' + it.bank_country,
  'Reason given: ' + it.reason,
  'Risk score: ' + it.risk + '/100' + (it.risk_flags ? ' (' + it.risk_flags + ')' : ''),
  '',
  'Nothing has been changed. The request is on hold for ' + it.cooling_hours + ' hours (cooling period) before it can be approved.',
  'Approve: ' + approve,
  'Reject:  ' + reject,
  '',
  'The link is single-use and expires in ' + cfg.link_ttl_hours + ' hours. It was sent only to the finance address already on file for this vendor - never to the address that requested the change.',
  '',
  'If you were not expecting this request: use the reject link, then call the vendor on the number you already have and report it. Never confirm bank details by replying to an email.',
  '',
  company
].join(NL);

return [{
  json: Object.assign({}, it, {
    token_hash: token_hash,
    created_at: now.toISOString(),
    cooling_until: addHours(it.cooling_hours),
    expires_at: addHours(cfg.link_ttl_hours),
    last_stage: 0,
    last_action_at: '',
    decided_by: '',
    note: '',
    to: it.finance_email,
    subject: '[Action required] Verify bank detail change for ' + it.vendor_name + ' (' + it.change_id + ')',
    body: body,
    text: 'Bank change held: ' + it.vendor_name + ' - risk ' + it.risk + '/100 - ' + it.change_id
  })
}];

// GuardRail - step 4: validate the one-click link. Nothing is written here.
const NL = String.fromCharCode(10);
function esc(v) {
  return String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function page(title, tone, lines) {
  return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(title) + '</title></head><body style="margin:0;background:#0B1020;color:#E6EDF7;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif"><div style="max-width:560px;margin:0 auto;padding:48px 24px"><div style="border-left:6px solid ' + tone + ';background:#141B2D;border-radius:10px;padding:24px"><h1 style="margin:0 0 12px;font-size:22px">' + esc(title) + '</h1>' + lines.map(function (l) { return '<p style="margin:8px 0;line-height:1.5;color:#B8C4D9">' + esc(l) + '</p>'; }).join('') + '</div><p style="color:#5C6A82;font-size:12px;margin-top:24px">Vendor bank-detail change guard</p></div></body></html>';
}
const q = $('Decision webhook').first().json.query || {};
const rows = $('Read changes (approval)').all().map(function (i) { return i.json; });
const token = String(q.t || '').toLowerCase();
const decision = String(q.d || '').toLowerCase();
const now = Date.now();
let outcome = 'invalid';
let row = null;
let reason = '';

if (!/^[a-f0-9]{64}$/.test(token)) {
  reason = 'malformed token';
} else {
  const h = String($('Hash decision token').first().json.token_hash || '').toLowerCase();
  row = rows.find(function (r) { return String(r.token_hash || '').toLowerCase() === h; }) || null;
  if (!row) reason = 'unknown token';
  else if (String(row.status || '').toUpperCase() !== 'PENDING_VERIFICATION') {
    outcome = 'already';
    reason = 'already ' + String(row.status || '').toLowerCase();
  } else if (decision !== 'approve' && decision !== 'reject') {
    reason = 'unknown decision';
  } else if (row.expires_at && new Date(row.expires_at).getTime() < now) {
    reason = 'link expired';
  } else if (decision === 'approve' && row.cooling_until && new Date(row.cooling_until).getTime() > now) {
    outcome = 'cooling';
    reason = 'cooling period ends ' + String(row.cooling_until || '').slice(0, 16).replace('T', ' ');
  } else {
    outcome = decision === 'approve' ? 'approved' : 'rejected';
  }
}

const who = row ? row.vendor_name + ' (' + row.change_id + ')' : 'unknown request';
const when = row && row.cooling_until ? String(row.cooling_until).slice(0, 16).replace('T', ' ') + ' UTC' : '';
let html = '';
if (outcome === 'approved') {
  html = page('Change approved', '#22D3A5', ['The new bank details for ' + who + ' are cleared for use.', 'Apply them in your banking or ERP system and confirm with the vendor by phone using the number on file.']);
} else if (outcome === 'rejected') {
  html = page('Change rejected', '#F87171', ['The change for ' + who + ' has been rejected. Nothing was altered.', 'If this request was not expected, treat it as a fraud attempt: call the vendor on the number on file.']);
} else if (outcome === 'cooling') {
  html = page('Still in the cooling period', '#FBBF24', ['This change cannot be approved yet.', 'The cooling period ends on ' + when + '. No action was taken; the link stays valid.']);
} else if (outcome === 'already') {
  html = page('Already handled', '#94A3B8', ['This request was already processed (' + reason + ').', 'No further action is needed and nothing was changed again.']);
} else if (reason === 'link expired') {
  html = page('Link expired', '#F87171', ['This link is no longer valid (' + reason + ').', 'Ask finance to start a new request; the old one stays on hold until the watchdog closes it.']);
} else {
  html = page('Invalid link', '#F87171', ['This link cannot be used (' + esc(reason) + ').', 'If you clicked a link from an email, check that you copied the whole URL.']);
}

const st = row ? String(row.status || '') : '';
return [{
  json: {
    outcome: outcome,
    reason: reason,
    change_id: row ? String(row.change_id || '') : '',
    vendor_name: row ? String(row.vendor_name || '') : '',
    new_iban_masked: row ? String(row.new_iban_masked || '') : '',
    requested_by: row ? String(row.requested_by || '') : '',
    finance_email: row ? String(row.finance_email || '') : '',
    finance_lead_email: row ? String(row.finance_lead_email || '') : '',
    status_before: st,
    cooling_until: row ? String(row.cooling_until || '') : '',
    html: html,
    event: outcome === 'invalid' ? 'LINK_DENIED' : '',
    actor: 'link',
    detail: outcome + (reason ? ' | ' + reason : ''),
    at: new Date().toISOString().slice(0, 16).replace('T', ' '),
    to: outcome === 'approved' ? (row ? row.finance_email : '') : (row ? row.requested_by : ''),
    subject: outcome === 'approved' ? 'Bank change approved - apply it for ' + (row ? row.vendor_name : '') : 'Bank change rejected for ' + (row ? row.vendor_name : ''),
    body: [
      'Request: ' + (row ? row.change_id + ' - ' + row.vendor_name : 'unknown'),
      'New IBAN: ' + (row ? row.new_iban_masked : 'n/a'),
      'Requested by: ' + (row ? row.requested_by : 'n/a'),
      '',
      outcome === 'approved'
        ? 'The change was approved after the cooling period. Apply it in the banking system and confirm with the vendor by phone using the number on file.'
        : 'The change was rejected. Nothing was altered. If this request was unexpected, treat it as fraud: call the vendor on the number on file.',
      ''
    ].join(NL)
  }
}];

// GuardRail - step 5: the watchdog. Decide which holds need a reminder or must expire.
// State lives in the sheet (last_stage), so a stage is never sent twice.
const rows = $input.all().map(function (i) { return i.json; });
const cfg = $('Config (watchdog)').first().json;
const NL = String.fromCharCode(10);
const out = [];
for (const r of rows) {
  if (String(r.status || '').toUpperCase() !== 'PENDING_VERIFICATION') continue;
  const created = new Date(r.created_at).getTime();
  if (!isFinite(created)) continue;
  const ageH = (Date.now() - created) / 3600000;
  const stage = ageH >= 72 ? 3 : ageH >= 48 ? 2 : ageH >= 24 ? 1 : 0;
  const last = Number(r.last_stage || 0);
  if (stage === 0 || stage <= last) continue;
  const lead = String(r.finance_lead_email || cfg.finance_lead || '');
  const finance = String(r.finance_email || '');
  const to = stage === 3 ? String(r.requested_by || '') : stage === 2 ? (lead || finance) : finance;
  if (!to) continue;
  const who = r.vendor_name + ' (' + r.change_id + ')';
  const hours = Math.round(ageH);
  let subject;
  let body;
  if (stage === 3) {
    subject = 'Hold expired, no change applied - ' + r.vendor_name;
    body = [
      'The bank detail change for ' + who + ' reached 72 hours without verification.',
      'It has been closed as EXPIRED. Nothing was applied.',
      '',
      'Requested by: ' + r.requested_by,
      'New IBAN: ' + r.new_iban_masked,
      'Risk: ' + r.risk + '/100 (' + (r.risk_flags || 'no flags') + ')',
      '',
      'If the vendor still needs the change, they must start a new request. Never re-send the old link.'
    ].join(NL);
  } else {
    subject = (stage === 2 ? '[Escalation] ' : '[Reminder] ') + 'Bank change still unverified - ' + r.vendor_name;
    body = [
      'The bank detail change for ' + who + ' has been waiting ' + hours + ' hours.',
      'Risk: ' + r.risk + '/100 (' + (r.risk_flags || 'no flags') + ')',
      'Cooling period ends: ' + String(r.cooling_until || '').slice(0, 16).replace('T', ' ') + ' UTC',
      '',
      'Use the approve or reject link in the original email. For safety the link is not re-sent.',
      stage === 2 ? 'This is the second reminder: the finance lead is now the recipient.' : ''
    ].join(NL);
  }
  out.push({
    json: {
      change_id: r.change_id,
      stage: stage,
      status_if_expire: stage === 3 ? 'EXPIRED' : '',
      to: to,
      subject: subject,
      body: body,
      text: (stage === 3 ? 'Expired: ' : 'Reminder ' + stage + ': ') + who + ' - ' + hours + 'h',
      event: stage === 3 ? 'HOLD_EXPIRED' : 'REMINDER_SENT',
      actor: 'watchdog',
      detail: 'stage ' + stage + ' at ' + hours + 'h',
      at: new Date().toISOString().slice(0, 16).replace('T', ' ')
    }
  });
}
return out;

// GuardRail - step 6: one daily line for the finance lead instead of per-vendor noise.
const rows = $input.all().map(function (i) { return i.json; });
const cfg = $('Config (watchdog)').first().json;
const NL = String.fromCharCode(10);
const now = Date.now();
const week = 7 * 86400000;
function st(r) { return String(r.status || '').toUpperCase(); }
function pending() { return rows.filter(function (r) { return st(r) === 'PENDING_VERIFICATION'; }); }
function recent(status) {
  return rows.filter(function (r) {
    const t = new Date(r.last_action_at || r.created_at || 0).getTime();
    return st(r) === status && isFinite(t) && t > now - week;
  }).length;
}
const p = pending();
const oldest = p.reduce(function (m, r) {
  const t = new Date(r.created_at || 0).getTime();
  return isFinite(t) ? Math.max(m, (now - t) / 3600000) : m;
}, 0);
const high = p.filter(function (r) { return Number(r.risk || 0) >= 70; }).length;
const overdueCooling = p.filter(function (r) { return new Date(r.cooling_until || 0).getTime() < now; }).length;

const body = [
  'Vendor bank-detail guard - daily digest',
  '',
  'Waiting for verification: ' + p.length,
  '  of which high risk: ' + high,
  '  past cooling, still waiting: ' + overdueCooling,
  '  oldest hold: ' + Math.round(oldest) + ' hours',
  '',
  'Last 7 days: approved ' + recent('APPROVED') + ' | rejected ' + recent('REJECTED') + ' | expired ' + recent('EXPIRED') + ' | manual review ' + recent('MANUAL_REVIEW'),
  '',
  p.length ? 'Open holds: ' + p.slice(0, 10).map(function (r) { return r.vendor_name + ' (' + r.risk + ')'; }).join(', ') : 'Nothing open. Good.',
  '',
  'Reminder: links are single-use and are never re-sent by email.'
].join(NL);

return [{ json: { to: cfg.finance_lead || '', subject: 'Bank-detail guard digest - ' + p.length + ' open', body: body, text: body.slice(0, 3500) } }];

// Format a short, safe alert - no payloads, no secrets.
const e = $json;
const NL = String.fromCharCode(10);
const lines = [];
lines.push('GuardRail error in "' + (e.workflow && e.workflow.name ? e.workflow.name : 'vendor bank change guard') + '"');
lines.push('Node: ' + (e.execution && e.execution.lastNodeExecuted ? e.execution.lastNodeExecuted : 'unknown'));
lines.push('Error: ' + (e.execution && e.execution.error && e.execution.error.message ? e.execution.error.message : 'no detail'));
if (e.execution && e.execution.url) lines.push('Execution: ' + e.execution.url);
return [{ json: { text: lines.join(NL) } }];
